#include <sstream>
using namespace alpha;
int checks=0;void check(bool b,const char* s){if(!b)throw std::runtime_error(s);++checks;std::cout<<"PASS "<<s<<std::endl;}
void advance(World& w,float seconds){for(int i=0;i<int(seconds*20)&&!w.result;++i)w.step(.05f);}
std::string snapshot(World& w){std::ostringstream out;w.save(out);return out.str();}
int main(){try{
 {World w;w.startMission(0);int g=w.gold,wood=w.wood;check(w.cheat("gold 123")&&w.gold==g+123&&w.wood==wood,"English gold command changes only player gold");check(w.cheat("legno 456")&&w.wood==wood+456,"Italian wood command");check(w.cheat("oil")&&w.oil==10000,"default oil amount");g=w.gold;wood=w.wood;check(w.cheat("resources 100")&&w.gold==g+100&&w.wood==wood+100&&w.oil==10100,"combined resources add atomically");for(auto cmd:{"gold -2","gold 0","gold 999999999999","gold 1 extra","gold 1000001","gold abc","gold 1.5","unknown"}){g=w.gold;wood=w.wood;check(!w.cheat(cmd)&&w.gold==g&&w.wood==wood,"invalid input cannot mutate resources");}w.gold=9999990;check(w.cheat("oro 100")&&w.gold==9999999,"resource bank capped at save-compatible maximum");}
 {World w;w.startMission(0);check(!w.train(1,Kind::Worker),"normal campaign requires a farm");w.cheat("supply on");w.cheat("free on");w.gold=w.wood=w.oil=0;check(w.capacity(0)==90&&w.train(1,Kind::Worker)&&w.gold==0,"supply and free cheats bypass farm and cost");check(w.cancel(1)&&w.gold==0,"free cancelled training never refunds unpaid resources");w.train(1,Kind::Worker);int pop=w.population(0,false);w.cheat("fast on");advance(w,.3f);check(w.population(0,false)==pop+1,"fast training actually spawns unit");w.cheat("normal");check(w.capacity(0)==10&&!w.cheatFree&&!w.cheatFast&&!w.cheatGod&&w.cheatsUsed,"normal disables continuous cheats and preserves used marker");check(!w.train(1,Kind::Worker),"normal restores mandatory farms");}
 {World w;w.startMission(0);check(!w.missionAllows(Kind::Academy),"normal early mission locks advanced content");w.cheat("unlock on");check(w.missionAllows(Kind::Academy)&&w.missionResearchAllows(Research::Town3),"unlock bypasses campaign technology gates");w.cheat("unlock off");check(!w.missionAllows(Kind::Academy),"campaign locks can be restored");check(w.build(2,{650,1190},Kind::Farm),"construction cheat test starts normal worker foundation");int site=w.entities.back().id;w.cheat("fast on");advance(w,6);check(w.get(site)&&w.get(site)->build==0&&!w.busy(*w.get(2)),"accelerated construction releases assigned worker");}
 {World w;w.reset();w.raidsEnabled=false;int enemy=w.add(Kind::Soldier,1,{1400,600});w.move(*w.get(enemy),{1600,600});w.cheat("freeze on");auto pos=w.get(enemy)->pos;int bank=w.enemyGold;advance(w,2);check(w.get(enemy)->pos==pos&&w.enemyGold==bank,"frozen enemies cannot move or spend");w.cheat("freeze off");advance(w,1);check(w.get(enemy)->pos!=pos,"unfrozen units resume their existing orders");
  w.cheat("god on");int target=7;float hp=w.get(target)->hp;auto point=w.get(target)->pos;w.shots.push_back({point,target,1,50,0,3,Kind::Archer});w.step(.05f);check(w.get(target)->hp==hp,"god mode blocks actual incoming damage");w.cheat("god off");w.shots.push_back({point,target,1,50,0,3,Kind::Archer});w.step(.05f);check(w.get(target)->hp<hp,"damage resumes after disabling god mode");
  w.cheat("freeze on");w.shots.push_back({point,target,1,10,0,3,Kind::Archer});w.zones.push_back({point,3,0,1});hp=w.get(target)->hp;w.step(.05f);check(w.get(target)->hp==hp&&w.shots.back().remaining==3&&w.zones.back().remaining==3,"freeze also suspends projectiles and hostile magic zones");}
 {World w;w.reset();w.raidsEnabled=false;int b=w.add(Kind::Barracks,0,{700,600});w.get(b)->selected=true;check(w.cheat("upgrade")&&w.get(b)->level==3&&w.get(b)->maxHp==def(Kind::Barracks).hp+300&&w.townLevel[0]==1,"selected upgrade affects selected structure");int f=w.add(Kind::Forge,0,{900,600});w.gold=w.wood=1000;check(w.research(f,Research::Weapons),"real research queue starts");check(w.cheat("research")&&w.upgrades[0][int(Research::Weapons)]==researchCatalog()[int(Research::Weapons)].maxLevel,"research cheat applies maximum levels");advance(w,30);check(w.upgrades[0][int(Research::Weapons)]==researchCatalog()[int(Research::Weapons)].maxLevel,"active research cannot exceed maximum after cheat");w.cheat("map on");check(!w.fogEnabled&&w.visibleAt({2300,400}),"map cheat reveals remote territory");w.cheat("map off");check(w.fogEnabled,"map fog can be restored");w.get(7)->hp=10;w.cheat("heal");check(w.get(7)->hp==w.get(7)->maxHp,"heal restores own units");}
 {World w;w.startMission(0);w.cheat("god on");w.cheat("fast on");w.cheat("freeze on");w.cheat("free on");w.cheat("unlock on");w.cheat("supply on");auto saved=snapshot(w);World copy;std::istringstream input(saved);check(copy.restore(input)&&snapshot(copy)==saved,"all cheat states round-trip through version 3 saves");copy.startMission(1);check(!copy.cheatGod&&!copy.cheatFreeze&&!copy.cheatsUsed,"new mission starts with cheats disabled");
  World old;old.startMission(0);auto modern=snapshot(old);auto first=modern.find('\n'),second=modern.find('\n',first+1),third=modern.find('\n',second+1);std::string version2="FRONTIERE_SAVE 2\n"+modern.substr(first+1,second-first)+modern.substr(third+1);World restored;std::istringstream v2(version2);check(restored.restore(v2)&&snapshot(restored)==modern,"previous version 2 saves load with cheats off");}
 {World w;w.reset();w.raidsEnabled=false;w.gold=9999999;auto worker=w.get(7);worker->pos=w.get(1)->pos+sf::Vector2f(100,0);worker->order=Order::Return;worker->target=1;worker->source=3;worker->cargo=10;worker->cargoKind=Kind::Mine;w.step(.05f);check(w.gold==9999999,"harvesting after max-resource cheat preserves bank ceiling");w.train(1,Kind::Worker);w.cheat("gold 100");w.cancel(1);auto saved=snapshot(w);World copy;std::istringstream in(saved);check(w.gold==9999999&&copy.restore(in),"refund at bank ceiling remains save compatible");}
 for(int n=0;n<missionCount;++n){World w;w.startMission(n);int crystal=n==10?w.archivist:-1;check(w.cheat("win")&&w.result==1&&w.missionStage==2,"win completes each campaign scenario and phases");if(crystal>=0)check(w.get(crystal)&&w.get(crystal)->team<0&&w.enemyRemaining()==0,"final victory removes every enemy and preserves the Worldstone");auto saved=snapshot(w);World restored;std::istringstream in(saved);check(restored.restore(in)&&restored.result==1,"cheated victory remains a valid saved mission");}
 std::cout<<"SUCCESS "<<checks<<" cheat simulation checks"<<std::endl;return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
